// src/components/Header.js
import React from 'react';
import { Link } from 'react-router-dom';
import './Header.css';

const Header = ({ user, onLogout }) => {
  // Format date and time with proper spacing
  const now = new Date();
  const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
  const timeOptions = { hour: '2-digit', minute: '2-digit' };
  
  const formattedDate = now.toLocaleDateString('en-US', dateOptions);
  const formattedTime = now.toLocaleTimeString('en-US', timeOptions);
  
  return (
    <header className="app-header">
      <div className="header-brand" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', margin: '0 auto' }}>
        <Link to="/dashboard">
          <h1>ER Triage System</h1>
        </Link>
        <div className="current-datetime">
          {formattedDate} &nbsp;|&nbsp; {formattedTime}
        </div>
      </div>
      
      <div className="header-user">
        <div className="user-info">
          <span className="user-name">{user?.full_name || 'User'}</span>
          <span className="user-role">{user?.username === 'doctor' ? 'Doctor' : 'Nurse'}</span>
        </div>
        <button onClick={onLogout} className="logout-button">
          Logout
        </button>
      </div>
    </header>
  );
};

export default Header;
